import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';

/// The app's sound effects — the Android half of src/lib/sfx.js.
///
/// The sounds are the same WAV files the web plays, generated by
/// scripts/generate-sfx.mjs into assets/sfx. Keep [file] in step with that
/// script's SOUNDS; test/services/sfx_service_test.dart checks every file exists.
enum Sfx {
  ring('ring', loop: true),
  ringback('ringback', loop: true),
  callConnected('call_connected'),
  callEnded('call_ended'),
  dmPing('dm_ping', minGap: Duration(milliseconds: 500)),
  voiceJoin('voice_join'),
  voiceLeave('voice_leave'),
  peerJoin('peer_join', minGap: Duration(milliseconds: 300)),
  peerLeave('peer_leave', minGap: Duration(milliseconds: 300));

  const Sfx(this.file, {this.loop = false, this.minGap});

  /// File name without extension, under assets/sfx.
  final String file;

  /// Repeats until stopped — the two ringing sounds.
  final bool loop;

  /// Minimum time between two plays of this sound. Only those that can arrive
  /// in a flurry have one: thirty people joining a channel must not be thirty
  /// overlapping chimes.
  final Duration? minGap;

  String get asset =>
      'sfx/$file.wav'; // relative to assets/, as AssetSource wants
  String get bundledPath => 'assets/$asset';
}

/// Whatever actually makes the noise. A seam so the rules in [SfxService] can be
/// tested without a phone, and so the audio package can be swapped.
abstract class SfxBackend {
  /// Gets every sound ready. Called once, at app start.
  Future<void> init();

  /// Starts [sfx] from the beginning (restarting it if it is already sounding).
  Future<void> start(Sfx sfx);

  Future<void> stop(Sfx sfx);
}

/// Decides WHETHER and WHEN a sound plays; the backend decides how.
///
/// Every failure is swallowed. A sound that cannot play must never take a call,
/// a message or a voice join down with it.
class SfxService {
  SfxService(this._backend, {DateTime Function()? now})
    : _now = now ?? DateTime.now;

  final SfxBackend _backend;
  final DateTime Function() _now;

  bool _enabled = true;
  bool _ready = false;
  final Map<Sfx, DateTime> _lastPlayed = {};

  bool get enabled => _enabled;
  bool get ready => _ready;

  Future<void> init() async {
    if (_ready) return;
    try {
      await _backend.init();
      _ready = true;
    } catch (e) {
      debugPrint('[sfx] could not initialise, sounds are off: $e');
    }
  }

  /// Fire-and-forget. Sounds are never worth awaiting.
  void play(Sfx sfx) {
    if (!_enabled || !_ready) return;
    final gap = sfx.minGap;
    final now = _now();
    final last = _lastPlayed[sfx];
    if (gap != null && last != null && now.difference(last) < gap) return;
    _lastPlayed[sfx] = now;
    _guard('start ${sfx.file}', () => _backend.start(sfx));
  }

  Future<void> stop(Sfx sfx) =>
      _guard('stop ${sfx.file}', () => _backend.stop(sfx));

  Future<void> stopAll() async {
    for (final s in Sfx.values) {
      await stop(s);
    }
  }

  /// Off means off: nothing new starts and anything ringing stops.
  void setEnabled(bool on) {
    _enabled = on;
    if (!on) stopAll();
  }

  Future<void> _guard(String what, Future<void> Function() action) async {
    try {
      await action();
    } catch (e) {
      debugPrint('[sfx] $what failed: $e');
    }
  }
}

/// Plays through the `audioplayers` package.
///
/// **Every player is created and configured once, in [init], at app start — and
/// that is deliberate.** On Android the package applies an audio context's
/// `audioMode` and `isSpeakerphoneOn` to the PHONE, globally, whenever a player's
/// context changes. Doing that the first time a sound plays, mid-call, would
/// reset the audio mode and speakerphone routing out from under a live voice
/// call. Configured up front, before any call can exist, nothing ever changes
/// afterwards: playing a sound only starts and stops a player.
class AudioplayersBackend implements SfxBackend {
  final Map<Sfx, AudioPlayer> _players = {};

  @override
  Future<void> init() async {
    for (final sfx in Sfx.values) {
      final player = AudioPlayer(playerId: 'sfx_${sfx.file}');
      await player.setReleaseMode(
        sfx.loop ? ReleaseMode.loop : ReleaseMode.stop,
      );
      await player.setAudioContext(_contextFor(sfx));
      // Loaded now, so a ring starts the instant a call does.
      await player.setSource(AssetSource(sfx.asset));
      _players[sfx] = player;
    }
  }

  AudioContext _contextFor(Sfx sfx) {
    return AudioContext(
      android: AudioContextAndroid(
        // The values the phone is ALREADY in. They are applied globally, once,
        // here — see the class note.
        isSpeakerphoneOn: false,
        audioMode: AndroidAudioMode.normal,
        stayAwake: false,
        contentType: AndroidContentType.sonification,
        // The ring follows the phone's ringer volume and silent mode, like any
        // ringtone; the rest are UI sounds and follow the system sounds volume.
        usageType: (sfx == Sfx.ring || sfx == Sfx.ringback)
            ? AndroidUsageType.notificationRingtone
            : AndroidUsageType.assistanceSonification,
        // Never take audio focus: a ping must not pause someone's music, and
        // must not interrupt a voice call's audio.
        audioFocus: AndroidAudioFocus.none,
      ),
      iOS: AudioContextIOS(
        // The category a voice call uses anyway. A different one here would be
        // switched globally the first time a ping played during a call.
        category: AVAudioSessionCategory.playAndRecord,
        options: const {
          AVAudioSessionOptions.mixWithOthers,
          AVAudioSessionOptions.defaultToSpeaker,
        },
      ),
    );
  }

  @override
  Future<void> start(Sfx sfx) async {
    final player = _players[sfx];
    if (player == null) return;
    await player.stop(); // back to the start if it was still sounding
    await player.resume();
  }

  @override
  Future<void> stop(Sfx sfx) async => _players[sfx]?.stop();
}
